-- Email delivery monitoring V2. Transactional append over HDA storage schema0.26.
-- No sends, routing changes, gate activation, retroactive data or telemetry coverage start.
BEGIN;
SET LOCAL statement_timeout='120s';SET LOCAL lock_timeout='10s';SET LOCAL idle_in_transaction_session_timeout='30s';
DO $email_admission$ BEGIN
 IF current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999 OR current_user<>session_user
 OR current_user::regrole IS DISTINCT FROM (SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4)) OR NOT ((SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4)) IS NOT NULL AND NOT EXISTS(
 SELECT 1 FROM pg_catalog.pg_default_acl d CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) a
 WHERE d.defaclrole=(SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4))
 AND (d.defaclnamespace=0 OR d.defaclnamespace IN (SELECT oid FROM pg_catalog.pg_namespace WHERE nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')))
 AND a.grantee<>d.defaclrole AND NOT (a.grantee=0 AND d.defaclobjtype='f' AND a.privilege_type='EXECUTE')))
 OR helpdesk_auth.schema_version() IS DISTINCT FROM '0.26.0'
 THEN RAISE EXCEPTION 'Qualified schema0.26 operator required' USING ERRCODE='HDM02';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('Consulte GEO schema upgrade',0));
 PERFORM pg_advisory_xact_lock(hashtextextended('helpdesk-notification-ledger-v1',0));
END$email_admission$;
