e(uuid)","helpdesk_auth.hdn_notification_claim(text, text, text, integer)","helpdesk_auth.hdn_notification_event(uuid, text)","helpdesk_auth.hdn_notification_lock(uuid)","helpdesk_auth.hdn_notification_native(jsonb, text)","helpdesk_auth.hdn_notification_plan(uuid)","helpdesk_auth.hdn_notification_routing(uuid)","helpdesk_auth.hdn_notification_save(uuid, jsonb, bigint, jsonb, text)","helpdesk_auth.hdn_notification_save_event(uuid, text, text)","helpdesk_auth.hdn_notification_source(uuid)","helpdesk_auth.hdn_notification_sources(integer)","helpdesk_auth.hdn_notification_template(text, integer)","helpdesk_auth.hdn_notification_write_plan(uuid, jsonb, jsonb)"]},{"name":"helpdesk_registration_worker","schemas":["helpdesk_auth"],"functions":["helpdesk_auth.hda02_apply(jsonb, jsonb)","helpdesk_auth.hda02_lock_scope(jsonb)","helpdesk_auth.hda02_next(jsonb)","helpdesk_auth.hda02_operation(jsonb, uuid)","helpdesk_auth.hda02_receipt(jsonb, uuid)","helpdesk_auth.hda02_storage_version()","helpdesk_auth.hda02_worker_target()"]}]}$email_contract$::jsonb as doc),
 expected_tables as (select * from pg_catalog.jsonb_to_recordset((select doc->'tables' from contract)) as x(name text,read boolean,"insert" boolean,updates text[])),
 expected_functions as (select * from pg_catalog.jsonb_to_recordset((select doc->'functions' from contract)) as x(signature text,definer boolean,execute boolean)),
 expected_triggers as (select * from pg_catalog.jsonb_to_recordset((select doc->'triggers' from contract)) as x("table" text,name text,"function" text,type integer,deferred boolean)),
 expected_constraints as (select * from pg_catalog.jsonb_to_recordset((select doc->'constraints' from contract)) as x("table" text,name text,type text)),
 expected_policies as (select * from pg_catalog.jsonb_to_recordset((select doc->'policies' from contract)) as x("table" text,name text,permissive boolean,command text)),
 expected_roles as (select * from pg_catalog.jsonb_to_recordset((select doc->'roles' from contract)) as x(name text,schemas text[],functions text[])),
 schemas as (select * from pg_catalog.pg_namespace where nspname=any(ARRAY['helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit']::text[])),
 tables as (select c.*,n.nspname||'.'||c.relname as full_name from pg_catalog.pg_class c join schemas n on n.oid=c.relnamespace where c.relkind in ('r','p','v','m','f','S')),
 functions as (select p.*,r.rolsuper,r.rolbypassrls,r.rolname as owner_name,
  n.nspname||'.'||p.proname||'('||pg_catalog.oidvectortypes(p.proargtypes)||')' as signature
  from pg_catalog.pg_proc p join schemas n on n.oid=p.pronamespace join pg_catalog.pg_roles r on r.oid=p.proowner),
 app as (select oid from pg_catalog.pg_roles where rolname='helpdesk_app'),
 clients as (select oid from pg_catalog.pg_roles where rolname in ('anon','authenticated','service_role'))
 select
 (select count(*)::integer from tables where relkind='r') as table_count,
 (select count(*)::integer from tables where not relrowsecurity or not relforcerowsecurity) as unsafe_tables,
 exists(select 1 from schemas n cross join lateral pg_catalog.aclexplode(coalesce(n.nspacl,pg_catalog.acldefault('n',n.nspowner))) a where a.grantee=0) as public_schema_access,
 exists(select 1 from schemas n cross join clients r where pg_catalog.has_schema_privilege(r.oid,n.oid,'USAGE,CREATE')) as client_schema_access,
 exists(select 1 from functions p cross join lateral pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a where a.grantee=0 and a.privilege_type='EXECUTE') as public_helper_execute,
 ((select count(*) from schemas)=4 and not exists(select 1 from schemas n
  where not pg_catalog.has_schema_privilege('helpdesk_app',n.oid,'USAGE')
   or pg_catalog.has_schema_privilege('helpdesk_app',n.oid,'CREATE,USAGE WITH GRANT OPTION'))) as schema_contract_ok,
 (not exists(select 1 from expected_tables e full join tables t on t.full_name=e.name
  where e.name is null or t.oid is null or t.relkind<>'r')) as table_contract_ok,
 (not exists(select 1 from tables t join expected_tables e on e.name=t.full_name where
  pg_catalog.has_table_privilege('helpdesk_app',t.oid,'SELECT') is distinct from e.read
  or pg_catalog.has_table_privilege('helpdesk_app',t.oid,'INSERT') is distinct from e."insert"
  or pg_catalog.has_table_privilege('helpdesk_app',t.oid,'UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
  or pg_catalog.has_table_privilege('helpdesk_app',t.oid,'SELECT WITH GRANT OPTION,INSERT WITH GRANT OPTION,UPDATE WITH GRANT OPTION'))
  ) as table_privileges_ok,
 (not exists(select 1 from tables t join expected_tables e on e.name=t.full_name
  join pg_catalog.pg_attribute a on a.attrelid=t.oid and a.attnum>0 and not a.attisdropped where
  pg_catalog.has_column_privilege('helpdesk_app',t.oid,a.attnum,'SELECT') is distinct from e.read
  or pg_catalog.has_column_privilege('helpdesk_app',t.oid,a.attnum,'INSERT') is distinct from e."insert"
  or pg_catalog.has_column_privilege('helpdesk_app',t.oid,a.attnum,'UPDATE') is distinct from (a.attname=any(e.updates))
  or pg_catalog.has_column_privilege('helpdesk_app',t.oid,a.attnum,'REFERENCES,SELECT WITH GRANT OPTION,INSERT WITH GRANT OPTION,UPDATE WITH GRANT OPTION'))
  ) as column_privileges_ok,
 (not exists(select 1 from tables t cross join clients r where
   pg_catalog.has_table_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
   or pg_catalog.has_any_column_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,REFERENCES'))
  and not exists(select 1 from functions p cross join clients r where pg_catalog.has_function_privilege(r.oid,p.oid,'EXECUTE'))
  and not exists(select 1 from tables t cross join lateral pg_catalog.aclexplode(coalesce(t.relacl,pg_catalog.acldefault('r',t.relowner))) a where a.grantee=0)
  and not exists(select 1 from tables t join pg_catalog.pg_attribute c on c.attrelid=t.oid
   cross join lateral pg_catalog.aclexplode(c.attacl) a where a.grantee=0)) as client_object_privileges_ok,
 (not exists(select 1 from expected_functions e full join functions p on p.signature=e.signature
  where e.signature is null or p.oid is null or p.prokind<>'f' or p.prosecdef is distinct from e.definer)) as helper_contract_ok,
 (not exists(select 1 from functions p join expected_functions e on e.signature=p.signature
  where pg_catalog.has_function_privilege('helpdesk_app',p.oid,'EXECUTE') is distinct from e.execute
   or pg_catalog.has_function_privilege('helpdesk_app',p.oid,'EXECUTE WITH GRANT OPTION'))) as helper_privileges_ok,
 (not exists(select 1 from functions p where p.owner_name='helpdesk_app'
  or not coalesce(p.proconfig @> array['search_path=""'] or p.proconfig @> array['search_path='],false)
  or (p.prosecdef and not (p.rolsuper or p.rolbypassrls)))) as helper_settings_ok,
 (not exists(select 1 from expected_triggers e left join tables t on t.full_name=e."table"
  left join pg_catalog.pg_trigger g on g.tgrelid=t.oid and g.tgname=e.name
  left join functions p on p.oid=g.tgfoid where g.oid is null or g.tgenabled not in ('O','A')
   or g.tgisinternal or g.tgtype<>e.type or g.tgdeferrable is distinct from e.deferred
   or g.tginitdeferred is distinct from e.deferred or p.signature is distinct from e."function")
  and not exists(select 1 from pg_catalog.pg_trigger g join tables t on t.oid=g.tgrelid where g.tgenabled not in ('O','A'))) as trigger_contract_ok,
 (not exists(select 1 from expected_constraints e left join tables t on t.full_name=e."table"
  left join pg_catalog.pg_constraint c on c.conrelid=t.oid and c.conname=e.name
  where c.oid is null or c.contype::text<>e.type or not c.convalidated)
  and not exists(select 1 from pg_catalog.pg_constraint c join tables t on t.oid=c.conrelid where not c.convalidated)) as constraint_contract_ok,
 (not exists(select 1 from pg_catalog.pg_index i join tables t on t.oid=i.indrelid where not i.indisvalid or not i.indisready)
  and exists(select 1 from pg_catalog.pg_index i join pg_catalog.pg_class x on x.oid=i.indexrelid
   join tables t on t.oid=i.indrelid where t.full_name='helpdesk_core.ticket_events' and x.relname='assignment_event_version'
    and i.indisunique and i.indisvalid and i.indisready)
  and (select count(*) from pg_catalog.pg_index i join pg_catalog.pg_class x on x.oid=i.indexrelid
   join tables t on t.oid=i.indrelid where t.full_name='helpdesk_audit.write_effects'
    and x.relname in ('write_effect_revision','write_effect_source')
    and i.indisunique and i.indisvalid and i.indisready and i.indpred is not null)=2) as index_contract_ok,
 ((select count(*) from pg_catalog.pg_policy p join tables t on t.oid=p.polrelid)=(select count(*) from expected_policies)
  and not exists(select 1 from expected_policies e left join tables t on t.full_name=e."table"
   left join pg_catalog.pg_policy p on p.polrelid=t.oid and p.polname=e.name where p.oid is null
    or p.polpermissive is distinct from e.permissive or p.polcmd::text<>e.command
    or p.polroles is distinct from array[(select oid from app)]::oid[])) as policy_contract_ok,
 ((select count(*) from expected_roles)=3 and not exists(select 1 from expected_roles e left join pg_catalog.pg_roles r on r.rolname=e.name where r.oid is null
   or r.rolsuper or r.rolbypassrls or r.rolcreaterole or r.rolcreatedb or r.rolreplication or r.rolinherit
   or EXISTS(
 SELECT 1 FROM pg_catalog.pg_auth_members m WHERE m.member=r.oid
 OR (m.roleid=r.oid AND NOT ((m.member=(SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4))
 AND m.grantor=10 AND EXISTS(SELECT 1 FROM pg_catalog.pg_roles bootstrap WHERE bootstrap.oid=10 AND bootstrap.rolsuper)
 AND m.admin_option AND NOT m.inherit_option AND NOT m.set_option) IS TRUE)))
   or exists(select 1 from schemas n where n.nspowner=r.oid or pg_catalog.has_schema_privilege(r.oid,n.oid,'USAGE') is distinct from (n.nspname=any(e.schemas)) or pg_catalog.has_schema_privilege(r.oid,n.oid,'CREATE,USAGE WITH GRANT OPTION'))
   or exists(select 1 from tables t where t.relowner=r.oid or pg_catalog.has_table_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') or pg_catalog.has_any_column_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,REFERENCES'))
   or exists(select 1 from functions p where p.proowner=r.oid or pg_catalog.has_function_privilege(r.oid,p.oid,'EXECUTE') is distinct from (p.signature=any(e.functions)) or pg_catalog.has_function_privilege(r.oid,p.oid,'EXECUTE WITH GRANT OPTION'))
 )) as reserved_roles_ok,
 ((SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4)) IS NOT NULL AND NOT EXISTS(
 SELECT 1 FROM pg_catalog.pg_default_acl d CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) a
 WHERE d.defaclrole=(SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4))
 AND (d.defaclnamespace=0 OR d.defaclnamespace IN (SELECT oid FROM pg_catalog.pg_namespace WHERE nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')))
 AND a.grantee<>d.defaclrole AND NOT (a.grantee=0 AND d.defaclobjtype='f' AND a.privilege_type='EXECUTE'))) as owner_defaults_ok,
 (pg_catalog.current_setting('server_version_num')::integer between 170000 and 179999
  and pg_catalog.current_setting('row_security')='on'
  and pg_catalog.current_setting('session_replication_role')='origin') as execution_settings_ok) inventory;IF email_catalogue_result.table_count<>88 OR email_catalogue_result.unsafe_tables<>0 OR email_catalogue_result.public_schema_access IS DISTINCT FROM false OR email_catalogue_result.client_schema_access IS DISTINCT FROM false OR email_catalogue_result.public_helper_execute IS DISTINCT FROM false OR email_catalogue_result.schema_contract_ok IS DISTINCT FROM true OR email_catalogue_result.table_contract_ok IS DISTINCT FROM true OR email_catalogue_result.table_privileges_ok IS DISTINCT FROM true OR email_catalogue_result.column_privileges_ok IS DISTINCT FROM true OR email_catalogue_result.client_object_privileges_ok IS DISTINCT FROM true OR email_catalogue_result.helper_contract_ok IS DISTINCT FROM true OR email_catalogue_result.helper_privileges_ok IS DISTINCT FROM true OR email_catalogue_result.helper_settings_ok IS DISTINCT FROM true OR email_catalogue_result.trigger_contract_ok IS DISTINCT FROM true OR email_catalogue_result.constraint_contract_ok IS DISTINCT FROM true OR email_catalogue_result.index_contract_ok IS DISTINCT FROM true OR email_catalogue_result.policy_contract_ok IS DISTINCT FROM true OR email_catalogue_result.execution_settings_ok IS DISTINCT FROM true OR email_catalogue_result.reserved_roles_ok IS DISTINCT FROM true OR email_catalogue_result.owner_defaults_ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Email monitor final catalogue mismatch' USING ERRCODE='HDM02';END IF;END$email_final$;
CREATE OR REPLACE FUNCTION helpdesk_auth.schema_version() RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT '0.27.0'::text$$;
COMMIT;
